import{_ as i}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as e,X as t}from"./chunks/vendor-vueuse.XPft87tp.js";const f=JSON.parse('{"title":"Vue3 的 DOM Diff 算法","description":"","frontmatter":{},"headers":[],"relativePath":"vue/vue3-dom-diff.md","filePath":"vue/vue3-dom-diff.md","lastUpdated":1786990830000}'),n={name:"vue/vue3-dom-diff.md"};function l(p,s,h,d,r,o){return e(),a("div",null,s[0]||(s[0]=[t(`<h1 id="vue3-的-dom-diff-算法" tabindex="-1">Vue3 的 DOM Diff 算法 <a class="header-anchor" href="#vue3-的-dom-diff-算法" aria-label="Permalink to &quot;Vue3 的 DOM Diff 算法&quot;">​</a></h1><h3 id="为什么需要-diff" tabindex="-1">为什么需要 Diff <a class="header-anchor" href="#为什么需要-diff" aria-label="Permalink to &quot;为什么需要 Diff&quot;">​</a></h3><p>Vue 的响应式更新粒度是组件级别。当组件内部某个响应式数据变化时，整个组件的 <code>render</code> 函数重新执行，生成一棵新的虚拟 DOM 树。如果直接将整棵虚拟 DOM 树映射为真实 DOM 操作并应用到页面上，会产生大量不必要的 DOM 更新——实际可能只有一两个节点发生了实质性变化。</p><p>虚拟 DOM 的作用是提供一个&quot;中间层&quot;，让框架有机会在内存中对比新旧两棵虚拟 DOM 树，找出真正需要更新的部分。Diff 算法就是完成这个对比的核心逻辑。</p><h3 id="vue3-diff-的整体策略" tabindex="-1">Vue3 Diff 的整体策略 <a class="header-anchor" href="#vue3-diff-的整体策略" aria-label="Permalink to &quot;Vue3 Diff 的整体策略&quot;">​</a></h3><p>Vue3 的 Diff 策略由三个层次组成：同层比较、双端指针、最长递增子序列。整体复杂度为 O(n)。</p><p><strong>同层比较</strong>：只对同一层级的节点进行对比，不跨层级。这是所有基于虚拟 DOM 的框架共同遵循的前提——跨层级的节点变动极其罕见，为它付出额外复杂度不划算。</p><p><strong>双端指针</strong>：在新旧两组子节点上各维护两个指针，分别指向头部和尾部，循环向内收缩。每一步比较四种情况：旧头 vs 新头、旧尾 vs 新尾、旧头 vs 新尾、旧尾 vs 新头。这种方式在处理列表的反转和移位时效率很高，大部分常见操作在首轮就能匹配。</p><p><strong>最长递增子序列（LIS）</strong>：当双端比较不足以匹配所有节点时，进入中间乱序区间的处理。Vue3 计算新节点在旧节点中的位置序列，对这个序列求最长递增子序列。这个子序列中的节点位置相对顺序是正确的，无需移动；其余节点按新的顺序插入或移位。这是 Vue3 相较于 Vue2 在同层比较层面的主要升级。</p><h3 id="与-vue2-diff-的对比" tabindex="-1">与 Vue2 Diff 的对比 <a class="header-anchor" href="#与-vue2-diff-的对比" aria-label="Permalink to &quot;与 Vue2 Diff 的对比&quot;">​</a></h3><p>Vue2 的 Diff 同样是同层 + 双端指针，但在两个方面不如 Vue3：</p><p><strong>编译阶段优化</strong>：Vue2 的 Diff 发生在纯运行时，每次更新都要遍历整棵虚拟 DOM 树。Vue3 在编译阶段就做了大量预处理：</p><ul><li><strong>静态提升</strong>：将模板中不会变化的纯静态节点从 <code>render</code> 函数中提升到外层，每次 <code>render</code> 执行时直接复用同一个 VNode 引用，避免重复创建</li><li><strong>Patch Flag</strong>：在动态节点上标记&quot;会变什么&quot;——<code>1</code> 表示文本会变、<code>2</code> 表示 class 会变、<code>8</code> 表示 props 会变。运行时 Diff 时只需检查被标记的部分，跳过所有静态节点</li><li><strong>Block Tree</strong>：将模板拆分为静态节点树和动态节点树（Block Tree），Diff 时只遍历动态节点树，整段静态内容被跳过</li></ul><p><strong>最长递增子序列</strong>：Vue2 在中间乱序区间的处理依赖纯粹的遍历和位置标记，Vue3 的 LIS 算法可以更精确地确定哪些节点的位置已经正确，减少不必要的 DOM 移动操作。</p><h3 id="与-react-diff-的对比" tabindex="-1">与 React Diff 的对比 <a class="header-anchor" href="#与-react-diff-的对比" aria-label="Permalink to &quot;与 React Diff 的对比&quot;">​</a></h3><p>React 的 Diff 策略同样是同层比较，但对节点的判断方式不同：</p><ul><li>React 通过 <code>type</code> 属性判断两个节点是否为同一类型——<code>type</code> 不同则整棵子树销毁重建</li><li>React 通过 <code>key</code> 属性在列表中复用节点实例，没有双端指针或 LIS 优化</li><li>React 的 Diff 与 Fiber 架构深度绑定，可中断、可分片执行，这是 React 并发模式的基石</li></ul><p>Vue3 的 Diff 追求&quot;用更少的 DOM 操作完成更新&quot;，React 的 Diff 追求&quot;让 Diff 本身可以被打断&quot;。两种设计取向的差异源于它们在不同架构层面对性能瓶颈的判断不同。</p><h3 id="一个具体的例子" tabindex="-1">一个具体的例子 <a class="header-anchor" href="#一个具体的例子" aria-label="Permalink to &quot;一个具体的例子&quot;">​</a></h3><div class="language-vue vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">template</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">div</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">h1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;静态标题&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">h1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">p</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> :class</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;dynamicClass&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;动态文本：{{ message }}&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">p</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">span</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;静态尾部&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">span</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">div</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">template</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>编译后，<code>&lt;h1&gt;</code> 和 <code>&lt;span&gt;</code> 被识别为纯静态节点并被提升。<code>&lt;p&gt;</code> 被打上 Patch Flag，标记其 <code>class</code> 和文本内容可能变化。Diff 阶段，Vue3 只看 <code>&lt;p&gt;</code> 的变化，<code>&lt;h1&gt;</code> 和 <code>&lt;span&gt;</code> 直接跳过。如果中间有一长串列表项，双端指针先快速匹配头尾不变的项，LIS 再处理中间变化的部分——整个过程不需要遍历每一对兄弟节点。</p>`,21)]))}const E=i(n,[["render",l]]);export{f as __pageData,E as default};
